function renderLegal(p){
  const L=lg();
  const sec=PF.lgSec&&L.s.find(x=>x[0]===PF.lgSec);
  if(!sec){
    PF.lgSec=null;pfSub(p,L.title);
    const g=pfGroup(p,'');
    /* ordine: prima l'avvertenza (app di trading), poi termini e privacy, contributi, crediti; i contatti in fondo */
    const ORD=['risk','terms','privacy','donate','credits','contact'];
    L.s.slice().sort((a,b)=>(ORD.indexOf(a[0])+99)%99-(ORD.indexOf(b[0])+99)%99).forEach(([k,title])=>{
      pfRow(g,LIC[k][0],title,lgsub(k),()=>{PF.lgSec=k;PF.keep=false;renderProfile();p.classList.add('pfin');setTimeout(()=>p.classList.remove('pfin'),400)},'chev',LIC[k][1]);
    });
    return;
  }
  const [k,title,items]=sec;
  pfSub(p,title);
  /* indietro: alle Note legali, non al Profilo */
  try{const bk=p.querySelector('.pfback');bk.lastChild.textContent=L.title;bk.onclick=()=>{PF.lgSec=null;renderProfile();p.classList.add('pfout');setTimeout(()=>p.classList.remove('pfout'),400)}}catch(e){}
  const box=document.createElement('div');box.className='lgtx';
  const ic=document.createElement('span');ic.className='lgtxic';ic.innerHTML=LIC[k][0];ic.style.color=LIC[k][1];box.appendChild(ic);
  items.forEach(t=>{const q=document.createElement('p');q.textContent=t;box.appendChild(q)});
  p.appendChild(box);
  if(k==='contact'){
    const g=pfGroup(p,'');
    pfRow(g,PIC.tg,lgsub('tg'),lgsub('tgsub'),()=>lgOpen(TG_DIRECT),'chev','#29a9eb');
    pfRow(g,PIC.mail,lgsub('mail'),SUPPORT_MAIL,()=>lgOpen('mailto:'+SUPPORT_MAIL),'chev','#a855f7');
  }
  if(k==='credits'){
    const g=pfGroup(p,'');
    pfRow(g,LIC.credits[0],'TradingView','tradingview.com',()=>lgOpen('https://www.tradingview.com/'),'chev',LIC.credits[1]);
  }
}
