  it(isdt('savedef'),()=>{IDEF[indKey(ind)]={inputs:JSON.parse(JSON.stringify(ind.inputs||{})),style:JSON.parse(JSON.stringify(ind.style||{})),tfv:JSON.parse(JSON.stringify(ind.tfv||{}))};lsSet('tc_inddef',IDEF);msg(isdt('saved'))});
