if(FIRST&&get('lang')==null){var nl=(navigator.language||'it').slice(0,2).toLowerCase();if(SUPPORTED.indexOf(nl)>=0&&nl!==lang){lang=nl;NXAPP.setLang(nl,false);}}
function t(k){return (T[lang]&&T[lang][k]!=null)?T[lang][k]:T.it[k];}
