    var inp=mk('input','acccode');inp.id=id;inp.setAttribute('inputmode','numeric');inp.setAttribute('pattern','[0-9]*');inp.autocomplete='one-time-code';inp.maxLength=7;inp.setAttribute('aria-label','Code');
    box.appendChild(inp);
